def f2(grid, marker=1):
    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    # collect markers per row and per column
    rmk={i:[j for j in range(w) if g[i][j]==marker] for i in range(h)}
    cmk={j:[i for i in range(h) if g[i][j]==marker] for j in range(w)}
    segs=[]  # ('r',row,j1,j2) or ('c',col,i1,i2)
    for i,js in rmk.items():
        if len(js)>=2: segs.append(('r',i,min(js),max(js)))
    for j,is_ in cmk.items():
        if len(is_)>=2: segs.append(('c',j,min(is_),max(is_)))
    # single markers on boundary: perpendicular full line
    for i,js in rmk.items():
        for j in js:
            if len(js)==1 and len(cmk[j])==1:
                if j==0 or j==w-1: segs.append(('r',i,0,w-1))
                elif i==0 or i==h-1: segs.append(('c',j,0,h-1))
    on=set()
    for t,a,b,c in segs:
        if t=='r':
            for j in range(b,c+1): on.add((a,j))
        else:
            for i in range(b,c+1): on.add((i,a))
    seen=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]==marker+1 and (i,j) not in seen:
                comp=[]; st=[(i,j)]; seen.add((i,j)); hit=False
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]==marker+1 and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y)); hit=hit or (x,y) in on
                if hit:
                    for a,b in comp: g[a][b]=marker
    for a,b in on: g[a][b]=marker
    return g
