from itertools import combinations
def f3(grid, marker=1):
    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    mk=[(i,j) for i in range(h) for j in range(w) if g[i][j]==marker]
    # aligned pairs
    pairs=[]
    for a,b in combinations(mk,2):
        if a[0]==b[0]: pairs.append((abs(a[1]-b[1]),a,b,'r'))
        elif a[1]==b[1]: pairs.append((abs(a[0]-b[0]),a,b,'c'))
    # brute-force min matching
    n=len(mk); best=None
    def rec(avail, chosen, cost):
        nonlocal best
        if not avail:
            if best is None or cost<best[0]: best=(cost,list(chosen))
            return
        a=avail[0]
        rec(avail[1:], chosen, cost)
        for i in range(1,len(avail)):
            b=avail[i]
            key=(a,b)
            pr=[p for p in pairs if {p[1],p[2]}=={a,b}]
            if pr:
                c,_,_,_=pr[0]
                rec(avail[:i]+avail[i+1:], chosen+[pr[0]], cost+c)
    rec(mk,[],0)
    segs=[]
    for c,a,b,o in best[1]:
        if o=='r': segs.append(('r',a[0],min(a[1],b[1]),max(a[1],b[1])))
        else: segs.append(('c',a[1],min(a[0],b[0]),max(a[0],b[0])))
    unmatched=set(mk)-{m for _,a,b,_ in best[1]}
    for (i,j) in unmatched:
        if j==0 or j==w-1: segs.append(('r',i,0,w-1))
        else: segs.append(('c',j,0,h-1))
    on=set()
    for t,a,b,c in segs:
        rng=range(b,c+1)
        if t=='r': on|={(a,j) for j in rng}
        else: on|={(i,a) for i in rng}
    seen=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]==marker+1 and (i,j) not in seen:
                comp=[]; st=[(i,j)]; seen.add((i,j)); hit=False
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]==marker+1 and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y)); hit=hit or (x,y) in on
                if hit:
                    for a,b in comp: g[a][b]=marker
    for a,b in on: g[a][b]=marker
    return g
