def rule_corridor(g, lines):
    """lines: set of ('r',i)/('c',j) FULL lines. Recolor block if crossed, or if strictly between two parallel lines (of same orient) covering it."""
    h,w=len(g),len(g[0])
    R={i for t,i in lines if t=='r'}; C={j for t,j in lines if t=='c'}
    out=[r[:] for r in g]
    for cs in comps2(g):
        rs=[a for a,b in cs]; cls=[b for a,b in cs]
        r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
        hit = any((r0<=i<=r1) for i in R) or any((c0<=j<=c1) for j in C)
        # corridor: strictly between two parallel lines on both sides
        for orient,S in (('r',R),('c',C)):
            lo=[x for x in S if x< (r0 if orient=='r' else c0)]
            hi=[x for x in S if x> (r1 if orient=='r' else c1)]
            if lo and hi: hit=True
        if hit:
            for a,b in cs: out[a][b]=1
    for i in R: out[i]=[1]*w
    for j in C:
        for i in range(h): out[i][j]=1
    return out

